struct R {
    verified: bool,
    patch: String,
}

struct F {
    repro: Option<R> = null,
}

test "mut through if let" {
    let mut fs: List<F> = [F { repro: Some(R { verified: false, patch: "p" }) }, F {}];
    for let f of &mut fs {
        if let Some(r) = &mut f.repro && !r.patch.is_empty() {
            r.verified = true;
        }
    }
    assert fs[0].repro matches { Some(r) && r.verified }, "MUTATION LOST";
}
